def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Convert relative path to absolute
    if not path.startswith('/'):
        if not cwd.startswith('/'):
            return None
        path = cwd.rstrip('/') + '/' + path

    # Split path into components and filter empty and '.' components
    components = [c for c in path.split('/') if c and c != '.']

    current = '/'
    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        # Handle '..'
        if comp == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            next_path = '/' + comp
        else:
            next_path = current + '/' + comp

        # Check if this path is a symlink
        if next_path in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the target and resolve it
            target = links[next_path]

            # If target is relative, it's relative to the directory containing the link
            if not target.startswith('/'):
                if current == '/':
                    target = '/' + target
                else:
                    target = current + '/' + target

            # Split remaining components and the target
            remaining = components[i+1:]
            target_components = [c for c in target.split('/') if c and c != '.']

            # Combine target components with remaining components
            components = target_components + remaining

            # Reset to root and restart from the beginning
            current = '/'
            i = 0
        else:
            # Regular component, just append it
            current = next_path
            i += 1

    # Remove trailing slash, except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

